"""Record perception metadata and optionally the annotated stream."""

import json
from collections import OrderedDict
from pathlib import Path
import time
import cv2
import numpy as np
import rclpy
from rclpy.callback_groups import MutuallyExclusiveCallbackGroup
from rclpy.executors import MultiThreadedExecutor
from rclpy.node import Node
from rclpy.signals import SignalHandlerOptions
from sensor_msgs.msg import Image
from std_msgs.msg import Bool, Float32, String
from .test_paths import find_test_root


def stamp_key(document):
    stamp = document.get("timestamp", document.get("stamp", {}))
    return int(stamp.get("sec", 0)), int(stamp.get("nanosec", 0))


class ResultRecorder(Node):
    def __init__(self):
        super().__init__("video_perception_result_recorder")
        root = find_test_root()
        defaults = {
            "output_directory": str(root / "output"),
            "metadata_filename": "perception_results.jsonl",
            "summary_filename": "performance_summary.json",
            "save_annotated_video": False,
            "annotated_video_filename": "annotated_result.mp4",
            "annotated_video_fps": 30.0,
        }
        for name, value in defaults.items():
            self.declare_parameter(name, value)
        configured_output = Path(self.get_parameter("output_directory").value).expanduser()
        if not configured_output.is_absolute():
            configured_output = root / configured_output
        self.output_directory = configured_output.resolve()
        self.output_directory.mkdir(parents=True, exist_ok=True)
        self.metadata_stream = (
            self.output_directory / self.get_parameter("metadata_filename").value
        ).open("w", encoding="utf-8")
        self.frame_indices = OrderedDict()
        self.pending = []
        self.latency_ms = None
        self.pipeline_latency_ms = None
        self.valid = False
        self.navigation_available = False
        self.status = "not_received"
        self.latencies = []
        self.published_frames = 0
        self.inference_frames = 0
        self.annotated_frames = 0
        self.invalid_perception_count = 0
        self.started = time.monotonic()
        self.writer = None
        self.save_video = bool(self.get_parameter("save_annotated_video").value)
        self.video_path = self.output_directory / self.get_parameter("annotated_video_filename").value

        self.data_callbacks = MutuallyExclusiveCallbackGroup()
        self.mask_callbacks = MutuallyExclusiveCallbackGroup()
        self.video_callbacks = MutuallyExclusiveCallbackGroup()

        self.create_subscription(String, "/video_test/frame_metadata", self._frame_metadata,
                                 50, callback_group=self.data_callbacks)
        self.create_subscription(String, "/perception/detections_json", self._detections,
                                 50, callback_group=self.data_callbacks)
        self.create_subscription(Float32, "/camera/inference_latency_ms", self._latency,
                                 50, callback_group=self.data_callbacks)
        self.create_subscription(Float32, "/camera/pipeline_latency_ms",
                                 self._pipeline_latency, 50,
                                 callback_group=self.data_callbacks)
        self.create_subscription(Bool, "/camera/perception_valid", self._valid, 50,
                                 callback_group=self.data_callbacks)
        self.create_subscription(Bool, "/camera/navigation_mask_available", self._navigation,
                                 50, callback_group=self.data_callbacks)
        self.create_subscription(String, "/camera/inference_status", self._status, 50,
                                 callback_group=self.data_callbacks)
        self.mask_metrics = {"road": OrderedDict(), "W_line": OrderedDict(),
                             "Y_line": OrderedDict()}
        for name, topic in (("road", "/camera/road_mask"),
                            ("W_line", "/camera/white_line_mask"),
                            ("Y_line", "/camera/yellow_line_mask")):
            self.create_subscription(
                Image, topic, lambda message, role=name: self._mask(role, message), 50,
                callback_group=self.mask_callbacks)
        if self.save_video:
            self.create_subscription(Image, "/perception/detections_image",
                                     self._annotated_image, 10,
                                     callback_group=self.video_callbacks)
        self.flush_timer = self.create_timer(0.05, self._flush_pending,
                                             callback_group=self.data_callbacks)

    def _frame_metadata(self, message):
        document = json.loads(message.data)
        self.frame_indices[stamp_key(document)] = int(document["frame_index"])
        self.published_frames += 1
        while len(self.frame_indices) > 2000:
            self.frame_indices.popitem(last=False)

    def _detections(self, message):
        document = json.loads(message.data)
        self.pending.append((time.monotonic(), document))

    def _latency(self, message):
        self.latency_ms = float(message.data)

    def _pipeline_latency(self, message):
        self.pipeline_latency_ms = float(message.data)

    def _mask(self, role, message):
        raw = np.frombuffer(message.data, dtype=np.uint8)
        mask = raw.reshape(message.height, message.step)[:, :message.width] != 0
        mono = np.ascontiguousarray(mask, dtype=np.uint8)
        area = int(cv2.countNonZero(mono))
        moments = cv2.moments(mono, binaryImage=True)
        bounding = cv2.boundingRect(mono) if area else None
        metric = {
            "pixel_area": area,
            "area_ratio": float(area / max(1, message.width * message.height)),
            "centroid": None if not area else
                [float(moments["m10"]/moments["m00"]),
                 float(moments["m01"]/moments["m00"])],
            "bounding_region": None if not area else
                [int(bounding[0]), int(bounding[1]),
                 int(bounding[0]+bounding[2]-1), int(bounding[1]+bounding[3]-1)],
        }
        key = (message.header.stamp.sec, message.header.stamp.nanosec)
        values = self.mask_metrics[role]
        values[key] = metric
        while len(values) > 2000:
            values.popitem(last=False)

    def _valid(self, message):
        self.valid = bool(message.data)

    def _navigation(self, message):
        self.navigation_available = bool(message.data)

    def _status(self, message):
        self.status = str(message.data)

    def _flush_pending(self, force=False):
        pending, self.pending = self.pending, []
        deferred = []
        now = time.monotonic()
        for received_at, document in pending:
            key = stamp_key(document)
            masks_ready = all(key in values for values in self.mask_metrics.values())
            if not force and not masks_ready and now-received_at < .2:
                deferred.append((received_at, document))
                continue
            latency = self.latency_ms
            if latency is not None:
                self.latencies.append(latency)
            output = {
                "timestamp": document.get("timestamp", document.get("stamp", {})),
                "video_frame_index": self.frame_indices.get(stamp_key(document)),
                "inference_latency_ms": latency,
                "pipeline_latency_ms": self.pipeline_latency_ms,
                "perception_valid": self.valid,
                "navigation_mask_available": self.navigation_available,
                "inference_status": self.status,
                "detections": document.get("detections", []),
            }
            output["frame_id"] = document.get("frame_id", "")
            output["detected_classes"] = sorted({
                item.get("class_name", "") for item in output["detections"]})
            output["class_instance_counts"] = dict(
                __import__("collections").Counter(
                    item.get("class_name", "") for item in output["detections"]))
            output["semantic_masks"] = {
                role: values.get(key) for role, values in self.mask_metrics.items()}
            self.metadata_stream.write(json.dumps(output, separators=(",", ":")) + "\n")
            self.inference_frames += 1
            if not self.valid:
                self.invalid_perception_count += 1
        self.pending.extend(deferred)
        if pending and len(deferred) != len(pending):
            self.metadata_stream.flush()

    def _annotated_image(self, message):
        if message.encoding.lower() != "bgr8":
            self.get_logger().error(f"Cannot save encoding {message.encoding!r}")
            return
        row_bytes = message.width * 3
        raw = np.frombuffer(message.data, dtype=np.uint8)
        frame = raw.reshape(message.height, message.step)[:, :row_bytes]
        frame = np.ascontiguousarray(frame.reshape(message.height, message.width, 3))
        if self.writer is None:
            fps = float(self.get_parameter("annotated_video_fps").value)
            if fps <= 0.0:
                raise ValueError("annotated_video_fps must be positive")
            self.writer = cv2.VideoWriter(
                str(self.video_path), cv2.VideoWriter_fourcc(*"mp4v"), fps,
                (message.width, message.height))
            if not self.writer.isOpened():
                raise RuntimeError(f"cannot open annotated video writer: {self.video_path}")
        self.writer.write(frame)
        self.annotated_frames += 1

    def close(self):
        self._flush_pending(force=True)
        if not self.metadata_stream.closed:
            self.metadata_stream.close()
        if self.writer is not None:
            self.writer.release()
        elapsed = max(time.monotonic() - self.started, 1e-9)
        array = np.asarray(self.latencies, dtype=float)
        summary = {
            "published_frame_count": self.published_frames,
            "inference_output_count": self.inference_frames,
            "annotated_frame_count": self.annotated_frames,
            "published_fps": self.published_frames / elapsed,
            "inference_fps": self.inference_frames / elapsed,
            "average_latency_ms": None if not array.size else float(array.mean()),
            "p95_latency_ms": None if not array.size else float(np.percentile(array, 95)),
            "maximum_latency_ms": None if not array.size else float(array.max()),
            "dropped_or_skipped_frame_count": max(0, self.published_frames - self.inference_frames),
            "invalid_perception_count": self.invalid_perception_count,
        }
        path = self.output_directory / self.get_parameter("summary_filename").value
        path.write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")

    def destroy_node(self):
        self.close()
        super().destroy_node()


def main():
    rclpy.init(signal_handler_options=SignalHandlerOptions.NO)
    node = ResultRecorder()
    executor = MultiThreadedExecutor(num_threads=3)
    executor.add_node(node)
    try:
        executor.spin()
    except KeyboardInterrupt:
        pass
    finally:
        try:
            executor.shutdown()
            node.destroy_node()
            if rclpy.ok():
                rclpy.shutdown()
        except KeyboardInterrupt:
            pass
